                run = run + 1 if grid[r][c] == color else 0
                if run > best:
                    best, marker = run, color
        for c in range(w):
            run = 0
            for r in range(h):
                run = run + 1 if grid[r][c] == color else 0
                if run > best:
                    best, marker = run, color

    if marker is None:
        return [row[:] for row in grid]

    # Objects are four-connected components of other colors.
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            col = grid[r][c]
            if col in (bg, marker) or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and
                        (yy, xx) not in seen and grid[yy][xx] == col):
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            objects.append(cells)

    marker_cells = [(r,c) for r in range(h) for c in range(w)
                    if grid[r][c] == marker]
    if not objects:
        return [row[:] for row in grid]

    # The marker's long stroke points toward the nearest object.
    target = min(objects, key=lambda cells: min(
        abs(y-r) + abs(x-c) for y,x in cells for r,c in marker_cells
    ))
    out = [row[:] for row in grid]
    for r,c in target:
        out[r][c] = marker
    return out
